                    details.append(f"movers missing from the list: {missing}")
                if extra:
                    details.append(f"robots listed without moving: {extra}")
                raise ValueError(
                    f"replay frame {frame_tick} 'moved' does not match the robots "
                    f"that changed position ({'; '.join(details)})"
                )

